+export function sanitizeFilename(input) {
+  if (typeof input !== 'string') {
+    throw new TypeError('Input must be a string');
+  }
+
+  // Normalize Unicode to NFC
+  const normalized = input.normalize('NFC');
+
+  // Remove ASCII control chars 0x00-0x1F and 0x7F
+  let result = '';
+  for (let i = 0; i < normalized.length; i++) {
+    const code = normalized.charCodeAt(i);
+    if ((code >= 0x00 && code <= 0x1F) || code === 0x7F) {
+      continue;
+    }
+    result += normalized[i];
+  }
+
+  // Replace Windows/path reserved chars < > : " / \\ | ? * with hyphen
+  const reservedChars = ['<', '>', ':', '"', '/', '\\', '|', '?', '*'];
+  for (const char of reservedChars) {
+    result = result.replace(new RegExp(escapeRegExp(char), 'g'), '-');
+  }
+
+  // Collapse whitespace runs to single space
+  result = result.replace(/\s+/g, ' ');
+
+  // Collapse repeated hyphens
+  result = result.replace(/-+/g, '-');
+
+  // Trim
+  result = result.trim();
+
+  // Strip trailing dots/spaces
+  result = result.replace(/[.\s]+$/, '');
+
+  // Empty result => underscore
+  if (result === '') {
+    return '_';
+  }
+
+  // Protect Windows reserved basenames case-insensitively
+  const reservedBasenames = [
+    'CON', 'PRN', 'AUX', 'NUL',
+    'COM1', 'COM2', 'COM3', 'COM4', 'COM5', 'COM6', 'COM7', 'COM8', 'COM9',
+    'LPT1', 'LPT2', 'LPT3', 'LPT4', 'LPT5', 'LPT6', 'LPT7', 'LPT8', 'LPT9'
+  ];
+
+  const upperResult = result.toUpperCase();
+  for (const reserved of reservedBasenames) {
+    if (upperResult === reserved) {
+      return '_' + result;
+    }
+  }
+
+  // Check if it's a filename with extension and the base matches reserved
+  const lastDotIndex = result.lastIndexOf('.');
+  if (lastDotIndex > 0) {
+    const base = result.substring(0, lastDotIndex);
+    const ext = result.substring(lastDotIndex + 1);
+    const upperBase = base.toUpperCase();
+    for (const reserved of reservedBasenames) {
+      if (upperBase === reserved) {
+        return '_' + result;
+      }
+    }
+  }
+
+  // Max 255 UTF-16 code units by truncating safely without ending high surrogate
+  const maxLen = 255;
+  let truncated = result.slice(0, maxLen);
+
+  // Check for incomplete surrogate pairs at the end
+  if (truncated.length > 0) {
+    const lastChar = truncated[truncated.length - 1];
+    const code = lastChar.charCodeAt(0);
+    // High surrogate: 0xD800-0xDBFF, Low surrogate: 0xDC00-0xDFFF
+    if ((code >= 0xD800 && code <= 0xDBFF) || (code >= 0xDC00 && code <= 0xDFFF)) {
+      // Truncate one more character to avoid incomplete surrogate
+      truncated = result.slice(0, maxLen - 1);
+    }
+  }
+
+  // Strip trailing dots/spaces again after truncation
+  truncated = truncated.replace(/[.\s]+$/, '');
+
+  if (truncated === '') {
+    return '_';
+  }
+
+  return truncated;
+}
+
+function escapeRegExp(string) {
+  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
+}

